import pandas as pd, re
from collections import Counter, defaultdict

df=pd.read_csv('benchmark/data.csv').sort_values('Year')
split_re=re.compile(r'\s*(?:,|&| and |\+|/|;|\|)\s*')
parse=lambda s:[p.strip() for p in split_re.split(str(s)) if p.strip()]

# longest gap between wins per composer
wins_by=defaultdict(list)
for _,r in df.iterrows():
    for n in parse(r['Composer']):
        wins_by[n].append(int(r['Year']))

gaps=[]
for n, years in wins_by.items():
    years=sorted(years)
    if len(years)>=2:
        for a,b in zip(years,years[1:]):
            gaps.append((b-a,n,a,b))

maxgap=max(gaps, key=lambda x:x[0])
print('max gap',maxgap)
# list top 10 gaps
for g in sorted(gaps, reverse=True)[:10]:
    print(g)

# streaks: consecutive-year wins by composer
streaks=[]
for n, years in wins_by.items():
    years=sorted(years)
    cur=[years[0]]
    for y in years[1:]:
        if y==cur[-1]+1:
            cur.append(y)
        else:
            if len(cur)>=2:
                streaks.append((len(cur),n,cur[0],cur[-1]))
            cur=[y]
    if len(cur)>=2:
        streaks.append((len(cur),n,cur[0],cur[-1]))

print('streaks',sorted(streaks, reverse=True)[:10])

# decade stats

df['Decade']=(df['Year']//10)*10
# concentration: share of wins by top composer per decade
for dec, g in df.groupby('Decade'):
    c=Counter()
    for s in g['Composer']:
        for n in parse(s):
            c[n]+=1
    topwins=max(c.values())
    topnames=[n for n,w in c.items() if w==topwins]
    print(dec,'ceremonies',len(g),'unique composers',len(set(sum([parse(s) for s in g['Composer']],[]))), 'topwins',topwins, topnames)
