{"cmd":"python - <<'PY'
import pandas as pd, re
from collections import Counter, defaultdict

df=pd.read_csv('benchmark/data.csv').sort_values('Year')
parse=lambda s:[p.strip() for p in re.split(r'\s*(?:,|&| and |\+|/|;|\|)\s*', str(s)) if p.strip()]

def decade(y):
    return (y//10)*10

# unique winner pool per decade (individuals)
uniq_by_dec=defaultdict(set)
for _,r in df.iterrows():
    for n in parse(r['Composer']):
        uniq_by_dec[decade(int(r['Year']))].add(n)

# repeat-winner ceremonies per decade: ceremony counts where any composer already won previously (global)
seen=set()
repeat_by_dec=Counter(); total_by_dec=Counter()
for _,r in df.iterrows():
    y=int(r['Year']); d=decade(y)
    names=parse(r['Composer'])
    total_by_dec[d]+=1
    if any(n in seen for n in names):
        repeat_by_dec[d]+=1
    for n in names:
        seen.add(n)

# concentration metric per decade: HHI-ish via shares of wins (individual)
conc_by_dec={}
for d, group in df.groupby(df['Year'].apply(decade)):
    c=Counter()
    for s in group['Composer']:
        for n in parse(s):
            c[n]+=1
    total=sum(c.values())
    hhi=sum((v/total)**2 for v in c.values()) if total else 0
    conc_by_dec[d]=hhi

print('Decade | ceremonies | unique winners | repeat ceremonies | repeat rate | concentration (HHI)')
for d in sorted(total_by_dec):
    print(d, total_by_dec[d], len(uniq_by_dec[d]), repeat_by_dec[d], round(repeat_by_dec[d]/total_by_dec[d],3), round(conc_by_dec[d],3))
PY"}

